from pathlib import Path

screen_path = Path('app/src/main/java/com/example/ui/screens/DevStudioScreen.kt')
data_path = Path('app/src/main/java/com/example/data/DeveloperDataManager.kt')

screen = screen_path.read_text()
data = data_path.read_text()

replacements = [
    (
        'import androidx.compose.foundation.clickable\n',
        'import androidx.compose.foundation.clickable\nimport androidx.compose.foundation.gestures.detectDragGesturesAfterLongPress\n'
    ),
    (
        'import androidx.compose.runtime.mutableStateListOf\n',
        'import androidx.compose.runtime.mutableStateListOf\nimport androidx.compose.runtime.mutableStateMapOf\n'
    ),
    (
        'import androidx.compose.ui.graphics.Brush\n',
        'import androidx.compose.ui.geometry.Offset\nimport androidx.compose.ui.geometry.Rect\nimport androidx.compose.ui.graphics.Brush\n'
    ),
    (
        'import androidx.compose.ui.layout.ContentScale\n',
        'import androidx.compose.ui.layout.ContentScale\nimport androidx.compose.ui.layout.boundsInRoot\nimport androidx.compose.ui.layout.onGloballyPositioned\nimport androidx.compose.ui.input.pointer.pointerInput\n'
    ),
]
for old, new in replacements:
    if old not in screen:
        raise SystemExit(f'missing import anchor: {old!r}')
    screen = screen.replace(old, new, 1)

old_state = '''    var imageTarget by remember { mutableStateOf<String?>(null) }\n    var imageVersion by remember { mutableStateOf(0) }\n    var busyText by remember { mutableStateOf<String?>(null) }\n'''
new_state = '''    var imageTarget by remember { mutableStateOf<String?>(null) }\n    var imageVersion by remember { mutableStateOf(0) }\n    var busyText by remember { mutableStateOf<String?>(null) }\n    val slotBounds = remember { mutableStateMapOf<String, Rect>() }\n    var draggingSlot by remember { mutableStateOf<String?>(null) }\n    var dragPosition by remember { mutableStateOf(Offset.Zero) }\n\n    fun keyForSlot(slotId: String): String? {\n        val pairIndex = slotId.substringBefore(':').toIntOrNull() ?: return null\n        val side = slotId.substringAfter(':').toIntOrNull() ?: return null\n        val pair = pairs.getOrNull(pairIndex) ?: return null\n        return if (side == 0) pair.first else pair.second\n    }\n\n    fun finishImageDrag() {\n        val source = draggingSlot\n        val target = slotBounds.entries.firstOrNull { (_, bounds) -> bounds.contains(dragPosition) }?.key\n        draggingSlot = null\n        if (source == null || target == null || source == target) return\n        val sourceKey = keyForSlot(source).orEmpty()\n        val targetKey = keyForSlot(target).orEmpty()\n        if (sourceKey.isBlank() || targetKey.isBlank()) return\n        DeveloperDataManager.swapOptionImages(context, sourceKey, targetKey)\n        imageVersion++\n    }\n'''
if old_state not in screen:
    raise SystemExit('missing editor state anchor')
screen = screen.replace(old_state, new_state, 1)

old_hint = '"Paare — tippe auf ein Bild, um es zu tauschen",'
new_hint = '"Paare — tippen = Bild ändern · lange drücken & ziehen = Bilder tauschen",'
if old_hint not in screen:
    raise SystemExit('missing pair hint anchor')
screen = screen.replace(old_hint, new_hint, 1)

old_editor_call = '''                            PairEditor(\n                                index = index,\n                                pair = pair,\n                                imageVersion = imageVersion,\n                                onChange = { newPair -> pairs[index] = newPair },\n                                onDelete = { pairs.removeAt(index) },\n                                onPickImage = { name ->\n                                    if (name.isNotBlank()) {\n                                        imageTarget = name\n                                        imagePicker.launch("image/*")\n                                    }\n                                }\n                            )\n'''
new_editor_call = '''                            PairEditor(\n                                index = index,\n                                pair = pair,\n                                imageVersion = imageVersion,\n                                draggingSlot = draggingSlot,\n                                onSlotBounds = { slotId, bounds -> slotBounds[slotId] = bounds },\n                                onDragStart = { slotId, rootPosition ->\n                                    draggingSlot = slotId\n                                    dragPosition = rootPosition\n                                },\n                                onDragMove = { delta -> dragPosition += delta },\n                                onDragEnd = { finishImageDrag() },\n                                onDragCancel = { draggingSlot = null },\n                                onChange = { newPair -> pairs[index] = newPair },\n                                onDelete = { pairs.removeAt(index) },\n                                onPickImage = { name ->\n                                    if (name.isNotBlank()) {\n                                        imageTarget = name\n                                        imagePicker.launch("image/*")\n                                    }\n                                }\n                            )\n'''
if old_editor_call not in screen:
    raise SystemExit('missing PairEditor call anchor')
screen = screen.replace(old_editor_call, new_editor_call, 1)

start = screen.index('@Composable\nprivate fun PairEditor(')
end = screen.index('@Composable\nprivate fun QuestionEditor(', start)
old_block = screen[start:end]
new_block = '''@Composable\nprivate fun PairEditor(\n    index: Int,\n    pair: Pair<String, String>,\n    imageVersion: Int,\n    draggingSlot: String?,\n    onSlotBounds: (String, Rect) -> Unit,\n    onDragStart: (String, Offset) -> Unit,\n    onDragMove: (Offset) -> Unit,\n    onDragEnd: () -> Unit,\n    onDragCancel: () -> Unit,\n    onChange: (Pair<String, String>) -> Unit,\n    onDelete: () -> Unit,\n    onPickImage: (String) -> Unit\n) {\n    Column(\n        modifier = Modifier\n            .fillMaxWidth()\n            .clip(RoundedCornerShape(14.dp))\n            .background(HarmonySurface)\n            .padding(10.dp)\n    ) {\n        Row(\n            modifier = Modifier.fillMaxWidth(),\n            horizontalArrangement = Arrangement.SpaceBetween,\n            verticalAlignment = Alignment.CenterVertically\n        ) {\n            Text("Paar ${index + 1}", fontSize = 11.sp, color = HarmonyMuted, fontWeight = FontWeight.Bold)\n            IconButton(onClick = onDelete, modifier = Modifier.size(28.dp)) {\n                Icon(Icons.Default.Delete, "Paar löschen", tint = Color(0xFFFF5252), modifier = Modifier.size(16.dp))\n            }\n        }\n        Spacer(Modifier.height(4.dp))\n        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n            val leftSlot = "$index:0"\n            val rightSlot = "$index:1"\n            OptionSlot(\n                slotId = leftSlot,\n                text = pair.first,\n                imageVersion = imageVersion,\n                isDragging = draggingSlot == leftSlot,\n                onSlotBounds = onSlotBounds,\n                onDragStart = onDragStart,\n                onDragMove = onDragMove,\n                onDragEnd = onDragEnd,\n                onDragCancel = onDragCancel,\n                onTextChange = { onChange(it to pair.second) },\n                onPickImage = {\n                    val key = if (pair.first.isBlank()) "img_${System.currentTimeMillis()}_a" else pair.first\n                    if (key != pair.first) onChange(key to pair.second)\n                    onPickImage(key)\n                },\n                modifier = Modifier.weight(1f)\n            )\n            OptionSlot(\n                slotId = rightSlot,\n                text = pair.second,\n                imageVersion = imageVersion,\n                isDragging = draggingSlot == rightSlot,\n                onSlotBounds = onSlotBounds,\n                onDragStart = onDragStart,\n                onDragMove = onDragMove,\n                onDragEnd = onDragEnd,\n                onDragCancel = onDragCancel,\n                onTextChange = { onChange(pair.first to it) },\n                onPickImage = {\n                    val key = if (pair.second.isBlank()) "img_${System.currentTimeMillis()}_b" else pair.second\n                    if (key != pair.second) onChange(pair.first to key)\n                    onPickImage(key)\n                },\n                modifier = Modifier.weight(1f)\n            )\n        }\n    }\n}\n\n@Composable\nprivate fun OptionSlot(\n    slotId: String,\n    text: String,\n    imageVersion: Int,\n    isDragging: Boolean,\n    onSlotBounds: (String, Rect) -> Unit,\n    onDragStart: (String, Offset) -> Unit,\n    onDragMove: (Offset) -> Unit,\n    onDragEnd: () -> Unit,\n    onDragCancel: () -> Unit,\n    onTextChange: (String) -> Unit,\n    onPickImage: () -> Unit,\n    modifier: Modifier = Modifier\n) {\n    val context = LocalContext.current\n    val isUserFacing = DevAssetStore.isUserFacingLabel(text)\n    val displayValue = if (isUserFacing) text else ""\n    var currentBounds by remember(slotId) { mutableStateOf(Rect.Zero) }\n\n    Column(modifier = modifier) {\n        Box(\n            modifier = Modifier\n                .fillMaxWidth()\n                .height(92.dp)\n                .onGloballyPositioned { coordinates ->\n                    currentBounds = coordinates.boundsInRoot()\n                    onSlotBounds(slotId, currentBounds)\n                }\n                .pointerInput(slotId, text) {\n                    detectDragGesturesAfterLongPress(\n                        onDragStart = { localPosition ->\n                            onDragStart(slotId, currentBounds.topLeft + localPosition)\n                        },\n                        onDrag = { change, dragAmount ->\n                            change.consume()\n                            onDragMove(dragAmount)\n                        },\n                        onDragEnd = onDragEnd,\n                        onDragCancel = onDragCancel\n                    )\n                }\n                .clip(RoundedCornerShape(10.dp))\n                .background(Color.Black)\n                .border(\n                    if (isDragging) 3.dp else 1.dp,\n                    if (isDragging) HarmonyGold else HarmonyLine,\n                    RoundedCornerShape(10.dp)\n                )\n                .clickable { onPickImage() }\n        ) {\n            if (text.isNotBlank()) {\n                AsyncImage(\n                    model = remember(text, imageVersion, TotImageProvider.version) {\n                        TotImageProvider.getImageUrl(text)\n                    },\n                    contentDescription = text,\n                    contentScale = ContentScale.Crop,\n                    modifier = Modifier.fillMaxSize()\n                )\n            }\n            Box(\n                modifier = Modifier\n                    .align(Alignment.BottomEnd)\n                    .padding(4.dp)\n                    .clip(RoundedCornerShape(6.dp))\n                    .background(Color.Black.copy(alpha = 0.65f))\n                    .padding(horizontal = 6.dp, vertical = 3.dp)\n            ) {\n                Text(if (isDragging) "Ziehen…" else "Bild ändern", fontSize = 9.5.sp, color = Color.White)\n            }\n        }\n        Spacer(Modifier.height(4.dp))\n        OutlinedTextField(\n            value = displayValue,\n            onValueChange = { newValue ->\n                onTextChange(\n                    DeveloperDataManager.renameOptionKeepingImage(\n                        context = context,\n                        oldKey = text,\n                        newLabel = newValue\n                    )\n                )\n            },\n            placeholder = { Text("Name (optional)", fontSize = 11.5.sp, color = HarmonyMuted) },\n            singleLine = false,\n            maxLines = 3,\n            textStyle = androidx.compose.ui.text.TextStyle(fontSize = 12.5.sp, color = HarmonyText),\n            colors = OutlinedTextFieldDefaults.colors(\n                focusedBorderColor = HarmonyPurpleLight,\n                unfocusedBorderColor = HarmonyLine\n            ),\n            shape = RoundedCornerShape(10.dp),\n            modifier = Modifier.fillMaxWidth()\n        )\n        if (isUserFacing && text.isNotBlank()) {\n            TextButton(\n                onClick = {\n                    onTextChange(\n                        DeveloperDataManager.renameOptionKeepingImage(\n                            context = context,\n                            oldKey = text,\n                            newLabel = ""\n                        )\n                    )\n                },\n                modifier = Modifier.fillMaxWidth()\n            ) {\n                Text("Bildtext nicht anzeigen", color = HarmonyMuted, fontSize = 10.5.sp)\n            }\n        }\n    }\n}\n\n'''
screen = screen[:start] + new_block + screen[end:]

anchor = '''    fun setImageFromUri(context: Context, optionName: String, uri: Uri): String? {\n        val key = optionName.trim()\n        if (key.isEmpty()) return null\n        val path = DevAssetStore.importFromUri(context, uri, key) ?: return null\n        imageOverrides[key] = path\n        saveData(context)\n        return path\n    }\n\n'''
addition = anchor + '''    /** Ändert nur den sichtbaren Namen; die Bildzuordnung bleibt erhalten. */\n    fun renameOptionKeepingImage(context: Context, oldKey: String, newLabel: String): String {\n        val sourceKey = oldKey.trim()\n        val typedLabel = newLabel.trim()\n        if (sourceKey.isEmpty()) return typedLabel\n        if (typedLabel == sourceKey) return sourceKey\n        if (typedLabel.isEmpty() && !DevAssetStore.isUserFacingLabel(sourceKey)) return sourceKey\n\n        val targetKey = if (typedLabel.isNotEmpty()) {\n            typedLabel\n        } else {\n            "img_hidden_${System.currentTimeMillis()}_${DevAssetStore.slug(sourceKey).take(24)}"\n        }\n\n        val path = imagePathFor(sourceKey)\n        if (!path.isNullOrBlank()) {\n            imageOverrides[targetKey] = path\n            TotImageProvider.setCustomImage(targetKey, path)\n        } else {\n            TotImageProvider.setAlias(targetKey, sourceKey)\n        }\n        return targetKey\n    }\n\n    /** Tauscht nur die Bildbelegung zweier Karten; Texte und Paarpositionen bleiben unverändert. */\n    fun swapOptionImages(context: Context, firstKey: String, secondKey: String) {\n        val first = firstKey.trim()\n        val second = secondKey.trim()\n        if (first.isEmpty() || second.isEmpty() || first == second) return\n\n        val firstPath = imagePathFor(first)\n        val secondPath = imagePathFor(second)\n\n        if (secondPath != null) {\n            imageOverrides[first] = secondPath\n            TotImageProvider.setCustomImage(first, secondPath)\n        } else {\n            imageOverrides.remove(first)\n            TotImageProvider.removeCustomImage(first)\n            TotImageProvider.setAlias(first, second)\n        }\n\n        if (firstPath != null) {\n            imageOverrides[second] = firstPath\n            TotImageProvider.setCustomImage(second, firstPath)\n        } else {\n            imageOverrides.remove(second)\n            TotImageProvider.removeCustomImage(second)\n            TotImageProvider.setAlias(second, first)\n        }\n\n        saveData(context)\n    }\n\n'''
if anchor not in data:
    raise SystemExit('missing DeveloperDataManager insertion anchor')
data = data.replace(anchor, addition, 1)

screen_path.write_text(screen)
data_path.write_text(data)
print('Applied Dev Studio drag-swap + label/image decoupling')
